import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime datetime;
  final double profitEarnedOrLoss;

  const Transaction({required this.coinName, required this.datetime, required this.profitEarnedOrLoss});
}

List<Transaction> sortTransactions(List<Transaction> transactions) {
  return transactions.sort((a, b) => b.profitEarnedOrLoss.compareTo(a.profitEarnedOrLoss));
}

Map<String, double> calculateAverageProfit(List<Transaction> transactions) {
  Map<String, double> averageProfits = {};
  for (final transaction in transactions) {
    if (!averageProfits.containsKey(transaction.coinName)) {
      averageProfits[transaction.coinName] = 0.0;
    }
    averageProfits[transaction.coinName] += transaction.profitEarnedOrLoss;
  }
  for (final key in averageProfits.keys) {
    averageProfits[key] /= transactions.length;
  }
  return averageProfits;
}

Map<String, double> calculateAverageLoss(List<Transaction> transactions) {
  Map<String, double> averageLosses = {};
