Here's a C++ program that generates the Fibonacci sequence using a recursive function:

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

// Recursive function to generate the Fibonacci sequence
int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    int num_elements;
    cout << "Enter the first two integers: ";
    cin >> num_elements;

    if (cin.fail() || num_elements <= 0) {
        throw runtime_error("Invalid input. Please enter a valid integer.");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> num_elements;

    if (cin.fail() || num_elements <= 0) {
        throw runtime_error("Invalid input. Please enter a valid integer.");
    }

    int a = 0;
    int b = 1;
    int sequence[num_elements];

    for (int i = 0; i < num_elements; i++) {
        sequence[i] = fibonacci(i, a, b);
        cout << sequence[i] << ", ";
    }

    cout << endl;

    return 0;
}
```

This program prompts the user to input the first two integers and the number of sequence elements to generate. It then uses a recursive function to generate the Fibonacci sequence and outputs the generated sequence, with each element separated by a comma and a space. The program includes error handling for invalid inputs, such as non-numeric inputs or negative numbers.

