Here's a React Hooks-based component that allows you to convert temperatures between Celsius, Fahrenheit, and Kelvin:

```jsx
import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  const handleConvert = (e) => {
    e.preventDefault();

    if (unit === 'celsius') {
      setTemperature((temperature * 9 / 5) + 32);
      setUnit('fahrenheit');
    } else if (unit === 'fahrenheit') {
      setTemperature((temperature - 32) * 5 / 9);
      setUnit('celsius');
    } else if (unit === 'kelvin') {
      setTemperature(temperature - 273.15);
      setUnit('celsius');
    }
  };

  return (
    <div>
      <h2>Temperature Converter</h2>
      <form onSubmit={handleConvert}>
        <label htmlFor="temperature">Enter the temperature:</label>
        <input type="number" id="temperature" value={temperature} onChange={(e) => setTemperature(parseFloat(e.target.value))} />
        <select id="unit" value={unit} onChange={(e) => setUnit(e.target.value)}>
          <option value="celsius">Celsius</option>
          <option value="fahrenheit">Fahrenheit</option>
          <option value="kelvin">Kelvin</option>
        </select>
        <button type="submit">Convert</button>
      </form>
      <p>Result: {temperature} {unit}</p>
    </div>
  );
};

export default TemperatureConverter;
```

