def num_to_english_scientific(num):
    if num == 0:
        return "zero"
    elif num < 0:
        return "negative " + num_to_english_scientific(-num)
    else:
        mantissa, exponent = num.as_tuple()
        words = []
        if mantissa != 0:
            words.append(num_to_english(mantissa))
        words.append("times ten to the power of")
        words.append(str(exponent))
        return " ".join(words)
```

