  };

  return (
    <div {...getComboboxProps()}>
      <input
        {...getInputProps({
          type: 'text',
          value: inputValue,
          onChange: handleInputChange,
          placeholder: 'Enter email address',
        })}
      />
      {isOpen && (
        <div {...getMenuProps()}>
          {selectedItem ? (
            <div>{selectedItem}</div>
          ) : (
            <ul>
              {items.map((item) => (
                <li key={item}>{item}</li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
};

export default EmailInputField;
```

