    var newPhrase = ""

    // Incorporate positive words and phrases
    let positiveWords = ["hope", "joy", "love", "blessings", "gratitude"]
    let randomPositiveWord = positiveWords.randomElement()!

    // Add a positive word or phrase at the beginning of the new phrase
