Here's a sample SQL code for creating a relational database with tables for books, authors, and genres. This design follows best practices for efficiency and avoiding redundancy:

```sql
-- Create the Books table
CREATE TABLE books (
    id INT PRIMARY KEY AUTO_INCREMENT,
    title VARCHAR(255) NOT NULL,
    publication_date DATE NOT NULL,
    publisher VARCHAR(255) NOT NULL,
    ISBN VARCHAR(13) NOT NULL UNIQUE,
    summary TEXT NOT NULL,
    author_id INT NOT NULL,
    genre_id INT NOT NULL
);

-- Create the Authors table
CREATE TABLE authors (
    id INT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    bio TEXT NOT NULL
);

-- Create the Genres table
CREATE TABLE genres (
    id INT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(255) NOT NULL,
    description TEXT NOT NULL
);

-- Add foreign keys to connect the tables
ALTER TABLE books ADD CONSTRAINT FK_books_authors FOREIGN KEY (author_id) REFERENCES authors(id);
ALTER TABLE books ADD CONSTRAINT FK_books_genres FOREIGN KEY (genre_id) REFERENCES genres(id);

-- Create indexes for faster querying
CREATE INDEX idx_books_title ON books (title);
CREATE INDEX idx_books_publication_date ON books (publication_date);
CREATE INDEX idx_books_publisher ON books (publisher);
CREATE INDEX idx_books_ISBN ON books (ISBN);
CREATE INDEX idx_books_summary ON books (summary);
CREATE INDEX idx_authors_name ON authors (name);
CREATE INDEX idx_authors_email ON authors (email);
CREATE INDEX idx_authors_bio ON authors (bio);
CREATE INDEX idx_genres_name ON genres (name);
CREATE INDEX idx_genres_description ON genres (description);
```

