Here's the `redis.js` file inside the `utils` folder with the required class and exports:

```javascript
// utils/redis.js
const { createClient } = require('redis');

class RedisClient {
  constructor() {
    const client = createClient();

    // Handle errors
    client.on('error', (err) => {
      console.error(`Redis Client Error: ${err}`);
    });

    this.client = client;
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (error) {
      console.error(`Redis Client Error: ${error}`);
      return false;
    }
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (error) {
      console.error(`Redis Client Error: ${error}`);
      throw error;
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.setex(key, duration, value);
    } catch (error) {
      console.error(`Redis Client Error: ${error}`);
      throw error;
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
    } catch (error) {
      console.error(`Redis Client Error: ${error}`);
      throw error;
    }
  }
}

const redisClient = new RedisClient();

module.exports = redisClient;
```

