To find the kth largest element in the given list, we can use the quickselect algorithm. This algorithm has a time complexity of O(n), which is efficient for large lists. Here's a Python implementation of the quickselect algorithm:

```python
def quickselect(numbers, k):
    def partition(left, right):
        pivot = numbers[right]
        i = left - 1
        for j in range(left, right):
            if numbers[j] <= pivot:
                i += 1
                numbers[i], numbers[j] = numbers[j], numbers[i]
        numbers[i + 1], numbers[right] = numbers[right], numbers[i + 1]
        return i + 1

    def quick_select(left, right, k):
        if left == right:
            return numbers[left]
        pivot_index = partition(left, right)
        if pivot_index == k - 1:
            return numbers[pivot_index]
        elif pivot_index > k - 1:
            return quick_select(left, pivot_index - 1, k)
        else:
            return quick_select(pivot_index + 1, right, k)

    return quick_select(0, len(numbers) - 1, k)

numbers = [140, 52, 172, 175, 201, 159, 291, 255, 93, 10, 111, 125, 221, 149, 92, 218, 199, 205, 108, 55]
k = 19

result = quickselect(numbers, k)
print("The", k, "-th largest element in the list is:", result)
```

